export default function ContactForm() {
  async function submitContact(formData: FormData) {
    'use server';

    const name = formData.get('name');
    const email = formData.get('email');
    const message = formData.get('message');

    if (!name || !email || !message) {
      // In a real app, you might return state to show an error to the user
      console.error('Validation failed: Name, email, and message are required.');
      return;
    }

    console.log('Contact message received:', { name, email, message });
  }

  return (
    <form action={submitContact} className="contact-form">
      <h2>Contact Us</h2>
      <div style={{ marginBottom: '1rem' }}>
        <label htmlFor="name" style={{ display: 'block' }}>Name</label>
        <input type="text" id="name" name="name" required style={{ width: '100%', padding: '0.5rem' }} />
      </div>
      <div style={{ marginBottom: '1rem' }}>
        <label htmlFor="email" style={{ display: 'block' }}>Email</label>
        <input type="email" id="email" name="email" required style={{ width: '100%', padding: '0.5rem' }} />
      </div>
      <div style={{ marginBottom: '1rem' }}>
        <label htmlFor="message" style={{ display: 'block' }}>Message</label>
        <textarea id="message" name="message" required style={{ width: '100%', padding: '0.5rem' }} />
      </div>
      <button type="submit" style={{ padding: '0.5rem 1rem' }}>Send Message</button>
    </form>
  );
}

